INSERT INTO "posts" ("id","user_id","content","diaper_id","pinned","created_at","repost_id","has_nsfw","is_announcement","spoiler_text","visibility","language","in_reply_to_id","in_reply_to_account_id","poll_id","edited_at","nbw_tid","nbw_pid","in_reply_to_type","mental_crisis") VALUES(67,26,replace('第一这个网站还有聊天功能啊，蛮全面的，就是每次发完一条信息网站就会重新刷新一下，显得不是那么流畅\n第二就是希望接收到他人消息的时候能够在页面顶部有弹窗显示，点击弹窗可以直接进入聊天界面\n第三如果能够有语音功能就更好了\n第四希望网站能够关联其他更多聊天软件，例如可以QQ登入等等\n第五，希望能够出APP，能够在手机上使用，并且手机端和网站端消息同步\n第六网站页面还是很简洁的，但是ai痕迹非常严重，如果能够加入自我的元素就更好了\n第七我希望能够推出交朋友的模式，类似于微信的附近找朋友，可以根据定位找寻附近的同好，并且可以添加朋友聊天，或者是摇一摇找朋友等等','\n',char(10)),NULL,0,'2026-06-12 15:08:57',NULL,0,0,'','public','zh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO "posts" ("id","user_id","content","diaper_id","pinned","created_at","repost_id","has_nsfw","is_announcement","spoiler_text","visibility","language","in_reply_to_id","in_reply_to_account_id","poll_id","edited_at","nbw_tid","nbw_pid","in_reply_to_type","mental_crisis") VALUES(68,12,'期待一下这个网站后续出应用版😋',NULL,0,'2026-06-13 11:22:40',NULL,0,0,'','public','zh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO "posts" ("id","user_id","content","diaper_id","pinned","created_at","repost_id","has_nsfw","is_announcement","spoiler_text","visibility","language","in_reply_to_id","in_reply_to_account_id","poll_id","edited_at","nbw_tid","nbw_pid","in_reply_to_type","mental_crisis") VALUES(69,37,replace('关于我\n我是「喹啉氨」本体哦～\n一个喜欢在三个地方同步更新日常的黏人DL宝宝。\n（小声：如果很久没回消息，可能是我在学校“坐牢”啦…）\n🌐 你可以在这里找到我\n我的日常碎片会同时留在：\n湿热一瞬间：KLqqq\n推特 (X)：@kuilinan\n宝宝新天地:喹啉氨\n如果你想要更靠近，也欢迎通过 QQ：3392787816 找到我～\n我们的小约定\n因为我在不同地方的账号不太一样…\n所以当你来加我时，请一定要轻轻告诉我“你是从哪个平台来的呀”～\n这就像我们的专属暗号，让我能瞬间认出你，给你一个大大的拥抱！(◕ᴗ◕✿)\n也可以在这里等我哦\n如果你暂时联系不上我，欢迎你直接在你看到的帖子下方留下你的联系方式～\n我放假的时候，就会像寻宝一样来找你、加你哒！😘','\n',char(10)),NULL,0,'2026-06-14 13:54:11',NULL,0,0,'','public','zh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0);
