INSERT INTO "posts" ("id","user_id","content","diaper_id","pinned","created_at","repost_id","has_nsfw","is_announcement","spoiler_text","visibility","language","in_reply_to_id","in_reply_to_account_id","poll_id","edited_at","nbw_tid","nbw_pid","in_reply_to_type","mental_crisis") VALUES(1085,47,replace('(￣_,￣ )还要工作，好烦的成人生活。整天就是工作下班吃饭睡觉。\n学徒还是少，不想干。\n晚上穿白天脱真麻烦','\n',char(10)),NULL,0,'2026-08-08 23:50:58',NULL,0,0,'','public','zh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0);
INSERT INTO "posts" ("id","user_id","content","diaper_id","pinned","created_at","repost_id","has_nsfw","is_announcement","spoiler_text","visibility","language","in_reply_to_id","in_reply_to_account_id","poll_id","edited_at","nbw_tid","nbw_pid","in_reply_to_type","mental_crisis") VALUES(1086,51,replace('宝宝们 后续来了！我分俩期发好吧。原本想着昨天晚上就把它发出来，但是太累了，那我就今天发吧 今天出发去男朋友家，我的OOTD（p1 没穿裤裤哈）然后男朋友他是自己买了个房，所以家里只有他自己一个人，我去他家的路上，想了个更好玩的想法，就是打算明天我和他俩人就在家里只穿裤裤生活一天（他已经同意了😃😃）\np2 已经到他家门口啦\np3 我让男朋友先洗个澡，因为我在家里已经洗了（感觉自己在说废话）他洗完澡，那我的行动也要开始了😳😳开始我跟他说，宝宝你躺床上把衣服脱了裤子也脱了，我给你换个尿不湿，他没拒绝就乖乖去做了，只是说不让我拍照（显然我并没有按他的去做😛😛）哈哈其实也是第一次见男生的dd，感觉还不错 帮男朋友搞了一会，男朋友叫我也把衣服脱了，然后说给我拍照，我觉得没问题👌哈哈，然后把我的内衣放在他上面拍照，宝宝他还害羞😳了哈哈哈哈哈哈，感觉我像个什么渣女一样 专门长爱这些喜欢男生哈哈哈哈！（偷偷跟你们说：不过你还别说男朋友还是个处，小处男😃但我摸着的感觉是真不错呀，我强烈建议姐妹们找男朋友就找这种的爽！）\n未完待续……（我可能后面几天才会更新，比较我要和宝宝培养感情 就这样吧宝宝们晚安啦）','\n',char(10)),NULL,0,'2026-08-09 00:21:33',NULL,0,0,'','public','zh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0);
