INSERT INTO "posts" ("id","user_id","content","diaper_id","pinned","created_at","repost_id","has_nsfw","is_announcement","spoiler_text","visibility","language","in_reply_to_id","in_reply_to_account_id","poll_id","edited_at","nbw_tid","nbw_pid","in_reply_to_type","mental_crisis") VALUES(1098,51,replace('宝宝和我❤\n后续来啦！\n昨天晚上，第一次和宝宝睡觉给宝宝抱裤裤，真是太好玩啦，睡觉前给他喂了奶奶和利尿药，让他自然的尿尿（主要是他说穿上后会li起来）\n我抱着宝宝睡觉感觉是一种很神奇的体验，我觉得裸睡可以促进和宝宝的关系，后面其实还想拍照，然后被宝宝按压在床上，手机也被收了 没有办法记录哈（宝宝们对不起呀）\n其实吧…🤗宝宝抚摸着我 我抱着他 宝宝说找到了小时候和妈妈一起睡觉的感觉很开心😃也希望可以继续下去…后面我打算经常来陪陪我的宝宝\n最后一张图是宝宝从昨天晚上11点到现在12的尿尿（还是很阔爱的大尿包，我也在里面尿了一点哟）今天剩下的时间，还是和宝宝一起抱裤裤（就不给大家看了哈 我要好好调教他哈哈哈）\n\n后面打算和宝宝去内蒙古玩自驾，到时候再给大家发照片（敬请期待吧！😜）\n（我已18啦，所以大家不用担心  我男朋友会对我做什么 他这人很是还蛮正经的 我很爱很爱❤的一个人 就算他想 我也愿意❤可惜他不想就摸摸😘也行吧）\n宝宝们也要好好的吃饭呀！下次再见👋啦！\n白白👋','\n',char(10)),NULL,0,'2026-08-09 04:14:49',NULL,0,0,'','public','zh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0);
