INSERT INTO "posts" ("id","user_id","content","diaper_id","pinned","created_at","repost_id","has_nsfw","is_announcement","spoiler_text","visibility","language","in_reply_to_id","in_reply_to_account_id","poll_id","edited_at","nbw_tid","nbw_pid","in_reply_to_type","mental_crisis") VALUES(1263,51,replace('谁能想到小时候如此单纯可爱的我长大之后如此瑟瑟🥰当时还在穿开裆裤尿不湿呢，现在也是呀！我从4岁后第一次穿裤裤是在14岁（好吧，要不算是裤裤，应该是安睡裤），10年！我又重新当上了一个乖宝宝，那年我认识17岁的他，我和他相差3岁，但他身上好像总有一种吸引着我的魅力，然后我们便相爱了。他是一个很优秀的男生，他好像在生活的方方面面都能安排的好好，无论是照顾我还是怎么怎么样，都很优秀，除了拍照（拍照跟拍鬼一样，这个我不喜欢，其他我都很喜欢🥰）我也和他说个我喜欢当宝宝的事，他当时肯定的说愿意，现在经过我的调教后，终于学会主动给我换裤裤啦\n现在的我18岁，他21了，我跟他是等我20就和你结婚，和你做…dady等着吧\n后面我应该不会在更新啦，我要去融入一个更为真实和充满挑战的生活啦！\n大家如果想和我交友的话，我也是很愿意滴！\n我把QQ号打在这里，我是不是的会回复大家滴QQ：3670314011\n注：本人坚决不会发布危害社会、损害国家利益的各类信息，严格遵守法律法规，自觉维护网络空间秩序与国家安全。若该账号出现传播不良信息的情况并非本人操作存在账号被盗冒用的可能，请各位宝宝提高警惕，切勿轻信相关内容。','\n',char(10)),NULL,0,'2026-08-13 12:57:25',NULL,0,0,'','public','zh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0);
