INSERT INTO "friend_request_snapshots" ("id","original_id","user_id","data","snapshot_type","created_at") VALUES(11,9,1,'{"id":9,"user_id":1,"title":"找家长","looking_for":"找家长","description":"测试要求：\n子曰：「君子不器。」子贡问君子一言。子曰：「驷不及舌。」季康子问政于孔子。孔子对曰：「政者，正也。子帅以正，孰敢不正常？」季康子患盗，问于孔子。孔子对曰：「苟子之不欲，虽赏之不窃。」季康子问：「使民敬、忠以劝，如之何？」子曰：「临之以庄，则敬；孝慈，则忠；举善而教不能，则劝。」或谓孔子曰：「子奚不为政？」子曰：「书云：『孝乎惟孝，友于兄弟，施于有政。』是亦为政，奚其为为政？」子张问政。子曰：「居之无倦，行之以忠。」子夏为莒父宰了，问政。子曰：「无欲速，无见小利。欲速，则不达；见小利，则大事不成。」叶公问政。","status":"active","created_at":"2026-07-12 06:08:44","user":{"username":"ZYongX","avatar":"https://img.abdl-space.top/file/1779220925584_1000012591.jpg","display_name":"ZYongX09"},"fields":[{"id":40,"request_id":9,"field_key":"生理性别","field_value":"男","is_primary":0,"sort_order":0},{"id":41,"request_id":9,"field_key":"年龄","field_value":"12","is_primary":0,"sort_order":1},{"id":42,"request_id":9,"field_key":"城市","field_value":"测试","is_primary":0,"sort_order":2},{"id":43,"request_id":9,"field_key":"手机号","field_value":"实例","is_primary":0,"sort_order":3},{"id":44,"request_id":9,"field_key":"微信","field_value":"实例","is_primary":0,"sort_order":4},{"id":45,"request_id":9,"field_key":"心理性别","field_value":"实例","is_primary":0,"sort_order":5},{"id":46,"request_id":9,"field_key":"Telegram","field_value":"实例","is_primary":0,"sort_order":6},{"id":47,"request_id":9,"field_key":"X(原推特)","field_value":"实例","is_primary":0,"sort_order":7},{"id":48,"request_id":9,"field_key":"宝宝新天地","field_value":"实例","is_primary":0,"sort_order":8},{"id":49,"request_id":9,"field_key":"QQ","field_value":"实例","is_primary":0,"sort_order":9},{"id":50,"request_id":9,"field_key":"爱好","field_value":"实例","is_primary":0,"sort_order":10}]}','delete','2026-07-13 12:01:08');
