PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,           -- PBKDF2: iterations$salt$derivedKey
  username TEXT UNIQUE NOT NULL,         -- 3–30 字符
  role TEXT NOT NULL DEFAULT 'user',     -- 'user' | 'admin'
  avatar TEXT,                           -- URL, 最长 2048
  age INTEGER,                           -- 1–150
  region TEXT,                           -- 最长 50
  weight REAL,                           -- kg
  waist REAL,                            -- cm
  hip REAL,                              -- cm
  style_preference TEXT,                 -- 最长 100
  bio TEXT,                              -- 最长 500
  email_verified INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, banned INTEGER DEFAULT 0, nbw_uid TEXT DEFAULT NULL, nbw_username TEXT DEFAULT NULL, password_changed_at DATETIME, invite_first_rating_bonus_at DATETIME, is_beta_user INTEGER NOT NULL DEFAULT 0, beta_registered_at DATETIME, header TEXT, has_app INTEGER DEFAULT 0, profile_fields TEXT DEFAULT '[]', display_name TEXT);
CREATE TABLE diapers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  brand TEXT NOT NULL,                   -- 最长 50
  model TEXT NOT NULL,                   -- 最长 100
  product_type TEXT NOT NULL,            -- 最长 20: '纸尿裤'/'拉拉裤'/'一体裤'
  thickness INTEGER NOT NULL,            -- 1–5 厚度等级
  absorbency_mfr TEXT NOT NULL,          -- 最长 50, 厂家标称吸水量
  absorbency_adult TEXT NOT NULL,        -- 最长 50, 成人实际估算
  is_baby_diaper INTEGER NOT NULL DEFAULT 0,
  comfort REAL,                          -- 1.0–5.0 先天舒适度
  popularity INTEGER DEFAULT 5,          -- 1–10 社区热度
  material TEXT NOT NULL,                -- 最长 500
  features TEXT NOT NULL,                -- 最长 1000
  avg_price TEXT NOT NULL,               -- 最长 50
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, official_url TEXT);
CREATE TABLE diaper_sizes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  diaper_id INTEGER NOT NULL,
  label TEXT NOT NULL,                   -- 最长 10, 如 'M'/'XL'
  waist_min INTEGER NOT NULL,
  waist_max INTEGER NOT NULL,
  hip_min INTEGER NOT NULL,
  hip_max INTEGER NOT NULL,
  UNIQUE(diaper_id, label),
  FOREIGN KEY (diaper_id) REFERENCES diapers(id) ON DELETE CASCADE
);
CREATE TABLE ratings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  diaper_id INTEGER NOT NULL,
  absorption_score INTEGER NOT NULL,     -- 1–10
  fit_score INTEGER NOT NULL,            -- 1–10
  comfort_score INTEGER NOT NULL,        -- 1–10
  thickness_score INTEGER NOT NULL,      -- 1–10
  appearance_score INTEGER NOT NULL,     -- 1–10
  value_score INTEGER NOT NULL,          -- 1–10
  review TEXT,                           -- 最长 500
  review_status TEXT NOT NULL DEFAULT 'approved',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, rewarded INTEGER NOT NULL DEFAULT 0,
  UNIQUE(user_id, diaper_id),
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (diaper_id) REFERENCES diapers(id)
);
CREATE TABLE feelings (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  diaper_id INTEGER NOT NULL,
  size TEXT NOT NULL,                    -- 最长 10
  looseness INTEGER NOT NULL,            -- -5..5
  softness INTEGER NOT NULL,             -- -5..5
  dryness INTEGER NOT NULL,              -- -5..5
  odor_control INTEGER NOT NULL,         -- -5..5
  quietness INTEGER NOT NULL,            -- -5..5
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(user_id, diaper_id, size),
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (diaper_id) REFERENCES diapers(id)
);
CREATE TABLE posts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  content TEXT NOT NULL,                 -- 最长 5000
  diaper_id INTEGER,
  pinned INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, repost_id INTEGER REFERENCES posts(id) ON DELETE SET NULL, has_nsfw INTEGER DEFAULT 0, is_announcement INTEGER DEFAULT 0, spoiler_text TEXT DEFAULT '', visibility TEXT DEFAULT 'public', language TEXT DEFAULT 'zh', in_reply_to_id INTEGER, in_reply_to_account_id INTEGER, poll_id INTEGER, edited_at DATETIME, nbw_tid INTEGER, nbw_pid INTEGER, in_reply_to_type TEXT DEFAULT NULL, mental_crisis INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (diaper_id) REFERENCES diapers(id)
);
CREATE TABLE post_comments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  post_id INTEGER NOT NULL,
  user_id INTEGER NOT NULL,
  parent_id INTEGER,
  content TEXT NOT NULL,                 -- 最长 2000
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (parent_id) REFERENCES post_comments(id)
);
CREATE TABLE likes (
  user_id INTEGER NOT NULL,
  target_type TEXT NOT NULL,             -- 'post' | 'comment'
  target_id INTEGER NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, unliked_at DATETIME,
  UNIQUE(user_id, target_type, target_id),
  FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE TABLE wiki_pages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  content TEXT NOT NULL,                 -- Markdown
  author_id INTEGER,
  diaper_id INTEGER,                     -- 可选 FK，非 NULL 时为纸尿裤绑定 Wiki
  version INTEGER DEFAULT 1,
  is_published INTEGER DEFAULT 1,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (author_id) REFERENCES users(id),
  FOREIGN KEY (diaper_id) REFERENCES diapers(id)
);
CREATE TABLE page_versions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  page_id INTEGER NOT NULL,
  content TEXT NOT NULL,
  version INTEGER NOT NULL,
  author_id INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (page_id) REFERENCES wiki_pages(id) ON DELETE CASCADE,
  FOREIGN KEY (author_id) REFERENCES users(id)
);
CREATE TABLE wiki_inline_comments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  page_id INTEGER NOT NULL,
  paragraph_hash TEXT NOT NULL,          -- 段落文本摘要，用于定位
  author_id INTEGER NOT NULL,
  content TEXT NOT NULL,                 -- 最长 1000
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (page_id) REFERENCES wiki_pages(id) ON DELETE CASCADE,
  FOREIGN KEY (author_id) REFERENCES users(id)
);
CREATE TABLE terms (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  term TEXT NOT NULL,                    -- 最长 50
  abbreviation TEXT,                     -- 最长 100
  definition TEXT NOT NULL,              -- 最长 2000
  category TEXT,                         -- 最长 30
  created_by INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (created_by) REFERENCES users(id)
);
CREATE TABLE experience (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL UNIQUE,
  current_exp INTEGER NOT NULL DEFAULT 0,
  total_exp INTEGER NOT NULL DEFAULT 0,
  current_level INTEGER NOT NULL DEFAULT 1, newbie_rating_bonus_count INTEGER NOT NULL DEFAULT 0, current_streak INTEGER NOT NULL DEFAULT 0, last_checkin_date TEXT, real_streak INTEGER NOT NULL DEFAULT 0, last_real_checkin_date TEXT,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE notifications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  type TEXT NOT NULL,                    -- 'like' | 'comment' | 'reply'
  message TEXT NOT NULL,
  related_id INTEGER,
  read INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP, actor_id INTEGER,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE api_keys (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  provider TEXT NOT NULL,                   -- 'deepseek' | 'openai' etc.
  key_value TEXT NOT NULL,                  -- 加密存储或明文（由管理员设置）
  label TEXT,                               -- 管理员备注
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE messages (   id INTEGER PRIMARY KEY AUTOINCREMENT,   sender_id INTEGER NOT NULL REFERENCES users(id),   receiver_id INTEGER NOT NULL REFERENCES users(id),   content TEXT NOT NULL,   read INTEGER DEFAULT 0,   created_at DATETIME DEFAULT CURRENT_TIMESTAMP , client_msg_id TEXT);
CREATE TABLE user_settings (   user_id INTEGER PRIMARY KEY REFERENCES users(id),   allow_messages INTEGER DEFAULT 1,   allow_messages_from TEXT DEFAULT 'all' );
CREATE TABLE post_images (   id INTEGER PRIMARY KEY AUTOINCREMENT,   post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,   image_url TEXT NOT NULL,   sort_order INTEGER DEFAULT 0,   created_at DATETIME DEFAULT CURRENT_TIMESTAMP , is_nsfw INTEGER DEFAULT 0, alt_text TEXT DEFAULT '', blurhash TEXT, preview_url TEXT, storage_provider TEXT CHECK (storage_provider IS NULL OR storage_provider IN ('cos', 'imgbed')));
CREATE TABLE follows (   id INTEGER PRIMARY KEY AUTOINCREMENT,   follower_id INTEGER NOT NULL REFERENCES users(id),   following_id INTEGER NOT NULL REFERENCES users(id),   created_at DATETIME DEFAULT CURRENT_TIMESTAMP,   UNIQUE(follower_id, following_id) );
CREATE TABLE comment_images (id INTEGER PRIMARY KEY AUTOINCREMENT, comment_id INTEGER NOT NULL, image_url TEXT NOT NULL, is_nsfw INTEGER DEFAULT 0, sort_order INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (comment_id) REFERENCES post_comments(id) ON DELETE CASCADE);
CREATE TABLE reports (id INTEGER PRIMARY KEY AUTOINCREMENT, reporter_id INTEGER NOT NULL, target_type TEXT NOT NULL, target_id INTEGER NOT NULL, reason TEXT NOT NULL, description TEXT, status TEXT DEFAULT "pending", resolved_by INTEGER, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (reporter_id) REFERENCES users(id), FOREIGN KEY (resolved_by) REFERENCES users(id));
CREATE TABLE rate_limits (
  key TEXT PRIMARY KEY,
  count INTEGER DEFAULT 1,
  window_start TEXT NOT NULL,
  expires_at TEXT NOT NULL
);
CREATE TABLE email_verifications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER,
  email TEXT NOT NULL,
  code_hash TEXT NOT NULL,
  type TEXT NOT NULL,
  used INTEGER DEFAULT 0,
  attempts INTEGER DEFAULT 0,
  expires_at TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE diaper_images (   id INTEGER PRIMARY KEY AUTOINCREMENT,   diaper_id INTEGER NOT NULL REFERENCES diapers(id) ON DELETE CASCADE,   image_url TEXT NOT NULL,   sort_order INTEGER DEFAULT 0,   created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE captcha_sessions (
  session_id    TEXT PRIMARY KEY,
  type          TEXT NOT NULL DEFAULT 'quantum',
  challenge     TEXT NOT NULL,
  answer_hash   TEXT NOT NULL,
  salt          TEXT NOT NULL,
  attempts      INTEGER NOT NULL DEFAULT 0,
  max_attempts  INTEGER NOT NULL DEFAULT 5,
  locked_until  INTEGER NOT NULL DEFAULT 0,
  ip            TEXT,
  created_at    INTEGER NOT NULL,
  expires_at    INTEGER NOT NULL,
  used          INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE captcha_api_keys (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  key_prefix  TEXT NOT NULL UNIQUE,         -- 前缀 "cv_xxxx" (前8字符，用于展示)
  key_hash    TEXT NOT NULL,                -- SHA-256 完整 key
  label       TEXT,                         -- 备注名称
  permissions TEXT NOT NULL DEFAULT 'create,check', -- 逗号分隔权限
  rate_limit  INTEGER NOT NULL DEFAULT 100, -- 每小时最大请求次数
  active      INTEGER NOT NULL DEFAULT 1,   -- 0=已禁用
  last_used   INTEGER,                      -- 最后使用时间 (unix seconds)
  use_count   INTEGER NOT NULL DEFAULT 0,   -- 累计调用次数
  created_at  INTEGER NOT NULL,
  owner_id    INTEGER                       -- 创建者 user id
);
CREATE TABLE oauth_clients (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  client_id     TEXT NOT NULL UNIQUE,          -- 公开标识: "oc_" + 32 hex
  client_secret TEXT NOT NULL,                 -- SHA-256 哈希存储，不存明文
  name          TEXT NOT NULL,                 -- 应用名称
  description   TEXT,                          -- 应用描述
  logo_url      TEXT,                          -- 应用 logo
  homepage_url  TEXT,                          -- 应用主页
  redirect_uris TEXT NOT NULL,                 -- JSON 数组: ["https://app.com/callback"]
  scopes        TEXT NOT NULL DEFAULT 'profile', -- 允许的 scope, 逗号分隔
  grant_types   TEXT NOT NULL DEFAULT 'authorization_code,refresh_token',
  owner_id      INTEGER NOT NULL,              -- 创建者 user id
  active        INTEGER NOT NULL DEFAULT 1,
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
, token_endpoint_auth_method TEXT NOT NULL DEFAULT 'client_secret_post');
CREATE TABLE oauth_codes (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  code          TEXT NOT NULL UNIQUE,          -- 随机 48 hex
  client_id     TEXT NOT NULL,
  user_id       INTEGER NOT NULL,
  redirect_uri  TEXT NOT NULL,
  scopes        TEXT NOT NULL,
  code_challenge        TEXT,                  -- PKCE: S256 challenge
  code_challenge_method TEXT,                  -- 'S256'
  expires_at    INTEGER NOT NULL,              -- 10 分钟
  used          INTEGER NOT NULL DEFAULT 0,
  created_at    INTEGER NOT NULL
);
CREATE TABLE oauth_tokens (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  access_token  TEXT NOT NULL UNIQUE,          -- 随机 48 hex
  refresh_token TEXT UNIQUE,                   -- 随机 48 hex, 可为空
  client_id     TEXT NOT NULL,
  user_id       INTEGER NOT NULL,
  scopes        TEXT NOT NULL,
  access_expires_at  INTEGER NOT NULL,         -- 1 小时
  refresh_expires_at INTEGER,                  -- 30 天
  revoked       INTEGER NOT NULL DEFAULT 0,
  created_at    INTEGER NOT NULL
);
CREATE TABLE brands (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, logo TEXT DEFAULT '', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, invert_dark INTEGER DEFAULT 0, invert_light INTEGER DEFAULT 0);
CREATE TABLE content_api_keys (id INTEGER PRIMARY KEY AUTOINCREMENT, key_prefix TEXT NOT NULL, key_hash TEXT NOT NULL UNIQUE, label TEXT, permissions TEXT NOT NULL DEFAULT 'read_posts,read_rankings,read_diapers', rate_limit INTEGER NOT NULL DEFAULT 200, active INTEGER NOT NULL DEFAULT 1, last_used INTEGER, use_count INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, owner_id INTEGER NOT NULL, FOREIGN KEY (owner_id) REFERENCES users(id));
CREATE TABLE ks_sub_keys (   id INTEGER PRIMARY KEY AUTOINCREMENT,   key_hash TEXT NOT NULL UNIQUE,   key_prefix TEXT NOT NULL,   name TEXT DEFAULT '',   channel_ids TEXT DEFAULT '[]',   quota_tokens INTEGER NOT NULL DEFAULT -1,   used_tokens INTEGER NOT NULL DEFAULT 0,   owner_id INTEGER NOT NULL,   enabled INTEGER NOT NULL DEFAULT 1,   last_used_at INTEGER,   created_at INTEGER NOT NULL DEFAULT (unixepoch()), rate_limit INTEGER NOT NULL DEFAULT 60,   FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE );
CREATE TABLE ks_usage_logs (   id INTEGER PRIMARY KEY AUTOINCREMENT,   sub_key_id INTEGER NOT NULL,   channel_id INTEGER NOT NULL,   model TEXT DEFAULT '',   prompt_tokens INTEGER NOT NULL DEFAULT 0,   completion_tokens INTEGER NOT NULL DEFAULT 0,   total_tokens INTEGER NOT NULL DEFAULT 0,   status INTEGER NOT NULL DEFAULT 200,   latency_ms INTEGER NOT NULL DEFAULT 0,   request_at INTEGER NOT NULL DEFAULT (unixepoch()),   FOREIGN KEY (sub_key_id) REFERENCES ks_sub_keys(id) ON DELETE CASCADE,   FOREIGN KEY (channel_id) REFERENCES ks_channels(id) ON DELETE CASCADE );
CREATE TABLE ks_channels (   id INTEGER PRIMARY KEY AUTOINCREMENT,   owner_id INTEGER NOT NULL,   name TEXT NOT NULL,   base_url TEXT NOT NULL,   api_key_enc TEXT NOT NULL,   models TEXT DEFAULT '[]',   enabled INTEGER NOT NULL DEFAULT 1,   created_at INTEGER NOT NULL DEFAULT (unixepoch()),   updated_at INTEGER NOT NULL DEFAULT (unixepoch()),   FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE );
CREATE TABLE security_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id TEXT,
  event_type TEXT NOT NULL,       -- low_behavior_score, context_mismatch, tamper_detected, etc.
  score INTEGER DEFAULT 0,        -- 行为评分 0-100
  ip TEXT,
  user_agent TEXT,
  details TEXT,                   -- JSON 详细数据
  created_at INTEGER NOT NULL     -- Unix timestamp
);
CREATE TABLE points (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL UNIQUE,
  balance INTEGER NOT NULL DEFAULT 0,
  total_earned INTEGER NOT NULL DEFAULT 0,
  total_spent INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE point_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  amount INTEGER NOT NULL CHECK (amount != 0),
  type TEXT NOT NULL,
  related_id INTEGER,
  source_type TEXT,
  source_id INTEGER,
  description TEXT,
  metadata TEXT,
  idempotency_key TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE exp_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  amount INTEGER NOT NULL CHECK (amount != 0),
  type TEXT NOT NULL,
  related_id INTEGER,
  source_type TEXT,
  source_id INTEGER,
  description TEXT,
  metadata TEXT,
  idempotency_key TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE daily_checkins (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  checkin_date TEXT NOT NULL,
  type TEXT NOT NULL DEFAULT 'normal',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(user_id, checkin_date),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE badges (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  icon TEXT NOT NULL,
  description TEXT NOT NULL,
  condition_type TEXT NOT NULL,
  condition_value INTEGER NOT NULL
);
CREATE TABLE user_badges (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  badge_key TEXT NOT NULL,
  unlocked_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  displayed INTEGER DEFAULT 0,
  UNIQUE(user_id, badge_key),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE site_settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "invite_codes" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code TEXT UNIQUE NOT NULL,
  creator_id INTEGER,
  used_by INTEGER,
  used_at DATETIME,
  expires_at DATETIME NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (creator_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (used_by) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE markers (
    user_id TEXT NOT NULL,
    timeline TEXT NOT NULL,
    last_read_id TEXT NOT NULL DEFAULT '0',
    version INTEGER NOT NULL DEFAULT 0,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, timeline)
  );
CREATE TABLE polls (id INTEGER PRIMARY KEY AUTOINCREMENT, status_id INTEGER NOT NULL, expires_at DATETIME NOT NULL, expired INTEGER DEFAULT 0, multiple INTEGER DEFAULT 0, hide_totals INTEGER DEFAULT 0, options TEXT NOT NULL DEFAULT '[]', voters_count INTEGER DEFAULT 0, votes_count INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (status_id) REFERENCES posts(id) ON DELETE CASCADE);
CREATE TABLE poll_votes (id INTEGER PRIMARY KEY AUTOINCREMENT, poll_id INTEGER NOT NULL, user_id INTEGER NOT NULL, choices TEXT NOT NULL DEFAULT '[]', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(poll_id, user_id), FOREIGN KEY (poll_id) REFERENCES polls(id) ON DELETE CASCADE);
CREATE TABLE announcements (id INTEGER PRIMARY KEY AUTOINCREMENT, content TEXT NOT NULL, starts_at TEXT, ends_at TEXT, all_day INTEGER DEFAULT 0, published INTEGER DEFAULT 1, published_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), created_at TEXT DEFAULT (datetime('now')));
CREATE TABLE announcement_reactions (id INTEGER PRIMARY KEY AUTOINCREMENT, announcement_id INTEGER NOT NULL, emoji TEXT NOT NULL, user_id INTEGER NOT NULL, created_at TEXT DEFAULT (datetime('now')), UNIQUE(announcement_id, emoji, user_id));
CREATE TABLE announcement_read_status (announcement_id INTEGER NOT NULL, user_id INTEGER NOT NULL, read_at TEXT DEFAULT (datetime('now')), PRIMARY KEY (announcement_id, user_id));
CREATE TABLE qr_login_sessions (
  id TEXT PRIMARY KEY,
  user_id INTEGER,
  status TEXT DEFAULT 'pending',  -- pending | scanned | authorized | expired
  created_at INTEGER DEFAULT (unixepoch()),
  expires_at INTEGER,
  ip TEXT,
  user_agent TEXT
);
CREATE TABLE jpush_registrations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  reg_id TEXT NOT NULL,
  created_at INTEGER DEFAULT (unixepoch()),
  last_active_at INTEGER DEFAULT (unixepoch())
);
CREATE TABLE lan_heartbeats (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL UNIQUE,
  last_active_at INTEGER DEFAULT (unixepoch())
);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE kv_store (key TEXT PRIMARY KEY, value TEXT, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE push_config (
  id INTEGER PRIMARY KEY DEFAULT 1,
  jpush_app_key TEXT,
  jpush_master_secret TEXT,
  jpush_enabled INTEGER DEFAULT 0,
  vapid_public_key TEXT,
  vapid_private_key TEXT,
  created_at INTEGER DEFAULT (unixepoch()),
  updated_at INTEGER DEFAULT (unixepoch())
);
CREATE TABLE push_subscriptions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  platform TEXT NOT NULL DEFAULT 'web',
  endpoint TEXT,
  p256dh TEXT,
  auth TEXT,
  registration_id TEXT,
  alias TEXT,
  tags TEXT,
  device_info TEXT,
  created_at INTEGER DEFAULT (unixepoch()),
  UNIQUE(user_id, platform, endpoint),
  UNIQUE(user_id, platform, registration_id)
);
CREATE TABLE push_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sender_id INTEGER,
  target_type TEXT NOT NULL,
  target_ids TEXT,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  url TEXT,
  platform TEXT DEFAULT 'all',
  sent_count INTEGER DEFAULT 0,
  fail_count INTEGER DEFAULT 0,
  jpush_msg_id TEXT,
  created_at INTEGER DEFAULT (unixepoch())
);
CREATE TABLE passkeys (
  id TEXT PRIMARY KEY,                    -- credential ID (base64url)
  user_id INTEGER NOT NULL,
  public_key BLOB NOT NULL,              -- P-256 公钥
  counter INTEGER DEFAULT 0,             -- 签名计数器
  device_type TEXT,                       -- 'singleDevice' | 'multiDevice'
  backed_up INTEGER DEFAULT 0,           -- 是否已备份
  transports TEXT,                        -- JSON array: ['internal', 'ble', etc.]
  nickname TEXT,                          -- 用户自定义名称（如"我的 iPhone"）
  created_at INTEGER DEFAULT (unixepoch()),
  last_used_at INTEGER DEFAULT (unixepoch()),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE friend_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  title TEXT NOT NULL,
  looking_for TEXT NOT NULL,
  description TEXT,
  status TEXT DEFAULT 'active',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE friend_request_fields (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  request_id INTEGER NOT NULL,
  field_key TEXT NOT NULL,
  field_value TEXT NOT NULL,
  is_primary INTEGER DEFAULT 0,
  sort_order INTEGER DEFAULT 0,
  FOREIGN KEY (request_id) REFERENCES friend_requests(id) ON DELETE CASCADE
);
CREATE TABLE friend_request_comments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  request_id INTEGER NOT NULL,
  user_id INTEGER NOT NULL,
  parent_id INTEGER,
  content TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (request_id) REFERENCES friend_requests(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (parent_id) REFERENCES friend_request_comments(id)
);
CREATE TABLE friend_request_reports (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  request_id INTEGER NOT NULL,
  reporter_id INTEGER NOT NULL,
  reason TEXT NOT NULL,
  evidence_urls TEXT,
  status TEXT DEFAULT 'pending',
  resolved_by INTEGER,
  admin_reply TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  resolved_at DATETIME,
  FOREIGN KEY (request_id) REFERENCES friend_requests(id),
  FOREIGN KEY (reporter_id) REFERENCES users(id),
  FOREIGN KEY (resolved_by) REFERENCES users(id)
);
CREATE TABLE friend_request_snapshots (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  original_id INTEGER NOT NULL,
  user_id INTEGER NOT NULL,
  data TEXT NOT NULL,
  snapshot_type TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE webauthn_challenges (
  id TEXT PRIMARY KEY,                   -- 挑战 ID（随机生成）
  challenge TEXT NOT NULL,               -- 挑战值（base64url）
  user_id INTEGER,                       -- 关联用户（注册时有，认证时可选）
  type TEXT NOT NULL,                    -- 'register' 或 'authenticate'
  expires_at INTEGER NOT NULL,           -- 过期时间（unixepoch）
  created_at INTEGER DEFAULT (unixepoch())
);
CREATE TABLE message_events (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, event_type TEXT NOT NULL, message_id INTEGER, peer_id INTEGER NOT NULL, read_up_to_id INTEGER, payload TEXT NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE message_outbox (event_id INTEGER PRIMARY KEY, dispatched_at INTEGER, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at INTEGER NOT NULL DEFAULT (unixepoch()), FOREIGN KEY(event_id) REFERENCES message_events(id));
CREATE TABLE media_uploads (
  id TEXT PRIMARY KEY NOT NULL,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  purpose TEXT NOT NULL CHECK (purpose IN ('status_original', 'status_preview', 'avatar', 'header', 'generic', 'release')),
  object_key TEXT NOT NULL UNIQUE,
  public_url TEXT NOT NULL,
  preview_upload_id TEXT REFERENCES media_uploads(id),
  preview_object_key TEXT,
  preview_url TEXT,
  mime_type TEXT NOT NULL,
  declared_size INTEGER NOT NULL CHECK (declared_size > 0),
  verified_size INTEGER CHECK (verified_size IS NULL OR verified_size >= 0),
  width INTEGER CHECK (width IS NULL OR width > 0),
  height INTEGER CHECK (height IS NULL OR height > 0),
  blurhash TEXT,
  storage_provider TEXT NOT NULL CHECK (storage_provider IN ('cos', 'imgbed')),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'complete', 'failed')),
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  expires_at INTEGER NOT NULL,
  CHECK (
    (preview_upload_id IS NULL AND preview_object_key IS NULL AND preview_url IS NULL)
    OR (preview_upload_id IS NOT NULL AND preview_object_key IS NOT NULL AND preview_url IS NOT NULL)
  )
);
CREATE TABLE private_books (
  id TEXT NOT NULL,
  owner_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  author TEXT NOT NULL,
  format TEXT NOT NULL,
  object_key TEXT NOT NULL,
  content_hash TEXT NOT NULL,
  content_md5 TEXT NOT NULL,
  declared_size INTEGER NOT NULL CHECK (declared_size > 0),
  verified_size INTEGER CHECK (verified_size IS NULL OR verified_size >= 0),
  parse_status TEXT NOT NULL DEFAULT 'pending' CHECK (parse_status IN ('pending', 'parsing', 'ready', 'failed')),
  upload_expires_at INTEGER NOT NULL,
  verification_started_at INTEGER,
  cleanup_status TEXT NOT NULL DEFAULT 'pending' CHECK (cleanup_status IN ('pending', 'deleting', 'monitoring', 'failed')),
  cleanup_attempted_at INTEGER,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),
  deleted_at INTEGER,
  PRIMARY KEY (owner_id, id),
  UNIQUE (owner_id, object_key)
);
CREATE TABLE novel_object_cleanup_jobs (
  object_key TEXT PRIMARY KEY NOT NULL,
  not_before INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'deleting', 'monitoring', 'failed')),
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  next_attempt_at INTEGER NOT NULL,
  claim_token TEXT,
  attempted_at INTEGER,
  last_error_status INTEGER,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE novel_sync_items (
  book_id TEXT NOT NULL,
  owner_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  item_type TEXT NOT NULL CHECK (item_type IN ('progress', 'bookmark', 'note')),
  item_id TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  client_updated_at INTEGER NOT NULL,
  server_updated_at INTEGER NOT NULL,
  deleted_at INTEGER,
  PRIMARY KEY (owner_id, item_type, item_id),
  FOREIGN KEY (owner_id, book_id) REFERENCES private_books(owner_id, id) ON DELETE CASCADE
);
CREATE TABLE novel_sync_changes (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  owner_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  book_id TEXT NOT NULL,
  item_type TEXT NOT NULL CHECK (item_type IN ('progress', 'bookmark', 'note')),
  item_id TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  client_updated_at INTEGER NOT NULL,
  deleted_at INTEGER,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  FOREIGN KEY (owner_id, book_id) REFERENCES private_books(owner_id, id) ON DELETE CASCADE
);
CREATE TABLE novels (
  id TEXT PRIMARY KEY,
  author_id INTEGER NOT NULL,
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 120),
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 2000),
  category TEXT NOT NULL CHECK (category IN ('fiction', 'fantasy', 'romance', 'science_fiction', 'mystery', 'history', 'essay', 'other')),
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'review_pending', 'published', 'rejected', 'archived')),
  idempotency_key TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),
  deleted_at INTEGER,
  FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE novel_volumes (
  id TEXT PRIMARY KEY,
  novel_id TEXT NOT NULL,
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 120),
  sort_order INTEGER NOT NULL CHECK (sort_order >= 0),
  idempotency_key TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),
  deleted_at INTEGER,
  FOREIGN KEY (novel_id) REFERENCES novels(id) ON DELETE CASCADE,
  UNIQUE (novel_id, id)
);
CREATE TABLE novel_chapters (
  id TEXT PRIMARY KEY,
  novel_id TEXT NOT NULL,
  volume_id TEXT NOT NULL,
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 120),
  sort_order INTEGER NOT NULL CHECK (sort_order >= 0),
  idempotency_key TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),
  deleted_at INTEGER,
  FOREIGN KEY (novel_id, volume_id) REFERENCES novel_volumes(novel_id, id) ON DELETE CASCADE
);
CREATE TABLE chapter_revisions (
  id TEXT PRIMARY KEY,
  owner_id INTEGER NOT NULL,
  chapter_id TEXT NOT NULL,
  body TEXT NOT NULL CHECK (length(body) <= 500000),
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'review_pending', 'approved', 'rejected', 'published', 'superseded')),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  create_idempotency_key TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),
  FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (chapter_id) REFERENCES novel_chapters(id) ON DELETE CASCADE,
  UNIQUE (owner_id, id)
);
CREATE TABLE novel_revision_operations (
  owner_id INTEGER NOT NULL,
  idempotency_key TEXT NOT NULL,
  revision_id TEXT NOT NULL,
  request_body TEXT NOT NULL,
  request_base_version INTEGER NOT NULL,
  response_body TEXT NOT NULL,
  response_chapter_id TEXT NOT NULL,
  response_status TEXT NOT NULL,
  response_version INTEGER NOT NULL,
  response_created_at INTEGER NOT NULL,
  response_updated_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  PRIMARY KEY(owner_id, idempotency_key),
  FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (owner_id, revision_id) REFERENCES chapter_revisions(owner_id, id) ON DELETE CASCADE
);
